{id:'q15',name:'Design a consent-first commons',node:'usmc',roles:['guardian','mediator'],tier:3,xp:80,traits:['Coordination','Care'],task:'Develop ground rules for public-source collaboration that protect privacy, civilian agency and institutional mandates.',outcome:'A permission and safety policy.'},
{id:'q16',name:'Integrate the five lessons',node:'un',roles:['mediator','builder'],tier:4,xp:100,traits:['Coordination','Diplomacy','Systems'],task:'Synthesize one cited finding from each edition, record contradictions and produce a nonviolent proposed peace-support decision pathway.',outcome:'A dated cross-domain synthesis with uncertainties.'}
